import re
for row in F:
 for key in ['summary_ru','details_ru']:
  vals=row[key] if isinstance(row[key],list) else [row[key]]
  vals=[re.sub(r'([а-яёА-ЯЁ])([A-Za-z0-9])',r'\1 \2',re.sub(r'([A-Za-z0-9])([а-яёА-ЯЁ])',r'\1 \2',v)) for v in vals]
  vals=[re.sub(r',(?=[А-Яа-яA-Za-z])',', ',v) for v in vals]
  vals=[re.sub(r'(?<=[а-яё])(?=[А-ЯЁ])',' ',v) for v in vals]
  row[key]=vals if isinstance(row[key],list) else vals[0]
(OUT/'notes.json').write_text(json.dumps(dict(functions=F),ensure_ascii=False,indent=2)+'\n',encoding='utf8')
